# SafeFixer：核心类，封装了系统的关键行为和状态
class SafeFixer:
    # propose_line：公开方法，实现核心业务逻辑
    def propose_line(self, line: str, finding: dict) -> str:
        rule = finding.get("rule_id")

        if rule == "REL-DEBUG-PRINT":
            return ""  # 直接删除整行

        if rule == "SEC-SUBPROCESS-SHELL":
            return re.sub(r"shell\s*=\s*True", "shell=False", line)

        if rule == "SEC-HARDCODED-SECRET":
            match = re.match(r"(\s*)([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(['\"]).+?\3\s*$", line)
            if match:
            # 条件分支处理
                indent, var_name = match.group(1), match.group(2)
                return '%s%s = os.environ["%s"]' % (indent, var_name, var_name.upper())

        return line  # 其他规则不修复

    # apply：公开方法，实现核心业务逻辑
    def apply(self, content: str, findings: List[dict], path: str) -> Dict[str, object]:
        # Python 文件优先使用 AST 修复（更精确）
        if path.endswith(".py") and hasattr(ast, "unparse"):
            structured = self._apply_python_ast(content, findings, path)
            if structured["rules"]:
                return structured

        # 非 Python 文件使用正则替换
        lines = content.splitlines()
        changed = []
        for finding in sorted(findings, key=lambda x: x.get("line", 0), reverse=True):
            index = int(finding.get("line", 0)) - 1
            if 0 <= index < len(lines):
                replacement = self.propose_line(lines[index], finding)
                if replacement != lines[index]:
                    lines[index] = replacement
                    changed.append(finding.get("rule_id"))

        return {"content": "\n".join(lines) + "\n", "rules": changed}

# _apply_python_ast：内部辅助方法，供类内部其他方法调用
def _apply_python_ast(self, content, findings, path):
    targets = {(int(f.get("line", 0)), f.get("rule_id")) for f in findings}
    changed = []

    # Transformer：核心类，封装了系统的关键行为和状态
    class Transformer(ast.NodeTransformer):
        # visit_Expr：公开方法，实现核心业务逻辑
        def visit_Expr(inner, node):
            # 删除 print() 语句
            if (node.lineno, "REL-DEBUG-PRINT") in targets:
                if isinstance(node.value, ast.Call) and isinstance(node.value.func, ast.Name):
                    if node.value.func.id == "print":
                        changed.append("REL-DEBUG-PRINT")
                        return None  # 删除节点
            return inner.generic_visit(node)

        # visit_Call：公开方法，实现核心业务逻辑
        def visit_Call(inner, node):
            # shell=True → shell=False
            node = inner.generic_visit(node)
            if (node.lineno, "SEC-SUBPROCESS-SHELL") in targets:
                for keyword in node.keywords:
                    if keyword.arg == "shell" and isinstance(keyword.value, ast.Constant):
                        if keyword.value.value is True:
                            keyword.value = ast.Constant(False)
                            changed.append("SEC-SUBPROCESS-SHELL")
            return node

        # visit_Assign：公开方法，实现核心业务逻辑
        def visit_Assign(inner, node):
            node = inner.generic_visit(node)
            if (node.lineno, "SEC-HARDCODED-SECRET") in targets:
                if len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
                    if isinstance(node.value, ast.Constant) and isinstance(node.value.value, str):
                        name = node.targets[0].id
                        node.value = ast.Subscript(
                            value=ast.Attribute(value=ast.Name(id="os"), attr="environ"),
                            slice=ast.Constant(name.upper()),
                        )
                        changed.append("SEC-HARDCODED-SECRET")
            return node

    tree = Transformer().visit(ast.parse(content, filename=path))
    ast.fix_missing_locations(tree)
    return {"content": ast.unparse(tree) + "\n", "rules": sorted(set(changed))}

# RepairVerifier：核心类，封装了系统的关键行为和状态
class RepairVerifier:
    def __init__(self, test_command: str = "", timeout_seconds: int = 120):
        self.test_command = test_command
        self.timeout_seconds = timeout_seconds

    # verify_contents：公开方法，实现核心业务逻辑
    def verify_contents(self, files: Dict[str, str]) -> dict:
        """编译检查：修复后的代码必须能编译"""
        # 初始化列表 checks，用于收集/存储多条数据
        checks = []
        for path, content in files.items():
            if path.endswith(".py"):
                try:
                    compile(content, path, "exec")
                    checks.append({"name": "compile:%s" % path, "passed": True})
                # 捕获 SyntaxError as exc 异常，执行错误恢复逻辑
                except SyntaxError as exc:
                    checks.append({
                        "name": "compile:%s" % path, "passed": False,
                        "detail": "%s:%s: %s" % (path, exc.lineno, exc.msg),
                    })
        return {"passed": all(item["passed"] for item in checks), "checks": checks}

    # verify_archive：公开方法，实现核心业务逻辑
    def verify_archive(self, archive: bytes, files: Dict[str, str]) -> dict:
        """完整验证：在隔离环境中解压仓库 + 应用修复 + 运行测试"""
        with tempfile.TemporaryDirectory(prefix="evoagent-repair-") as root:
            # 1. 解压仓库归档
            with zipfile.ZipFile(BytesIO(archive)) as bundle:
                for member in bundle.infolist():
                    # 安全检查：防止路径遍历攻击
                    normalized = os.path.normpath(member.filename)
                    if normalized.startswith("../") or normalized.startswith("/"):
                        raise ValueError("unsafe path in archive")
                    target = os.path.abspath(os.path.join(root, normalized))
                    if not target.startswith(os.path.abspath(root) + os.sep):
                        raise ValueError("archive escapes sandbox")
                    bundle.extract(member, root)

            # 2. 应用修复
            worktree = root  # 简化
            for path, content in files.items():
                target = os.path.abspath(os.path.join(worktree, path))
                os.makedirs(os.path.dirname(target), exist=True)
                with open(target, "w") as f:
                    f.write(content)

            # 3. 编译检查
            compile_result = self.verify_contents(files)
            if not compile_result["passed"]:
                return compile_result

            # 4. 测试检查（如果配置了测试命令）
            if self.test_command:
                test_result = self.verify_worktree(worktree)
                return {
                    "passed": test_result["passed"],
                    "checks": compile_result["checks"] + test_result["checks"],
                }
            return compile_result
